import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Intersezioni fra due circonferenze","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/d_geometria-cartesiana/dd/ddch.md","filePath":"lezioni/d_geometria-cartesiana/dd/ddch.md"}`),a={name:`lezioni/d_geometria-cartesiana/dd/ddch.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="intersezioni-fra-due-circonferenze" tabindex="-1">Intersezioni fra due circonferenze <a class="header-anchor" href="#intersezioni-fra-due-circonferenze" aria-label="Permalink to “Intersezioni fra due circonferenze”">​</a></h1><p>Osservando due circonferenze nel piano puoi vedere che, se si intersecano, hanno <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6444em;"></span><span class="mord">2</span></span></span></span> punti in comune.</p><p>Quindi, facendo il sistema fra le due circonferenze deve essere possibile trovare le coordinate dei punti.</p><p>Però un&#39;equazione di una circonferenza è di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>secondo\xA0grado</mtext></mrow><annotation encoding="application/x-tex">\\text{secondo grado}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">secondo\xA0grado</span></span></span></span></span>, quindi il sistema fra le due circonferenze sarebbe di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>quarto\xA0grado</mtext></mrow><annotation encoding="application/x-tex">\\text{quarto grado}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">quarto\xA0grado</span></span></span></span></span>, ed io non sono capace di risolvere un&#39;equazione di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>quarto\xA0grado</mtext></mrow><annotation encoding="application/x-tex">\\text{quarto grado}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">quarto\xA0grado</span></span></span></span></span>.</p><p>Per risolvere il problema possiamo utilizzare una proprietà delle equazioni: la somma o la differenza termine a termine fra due equazioni valide è ancora un&#39;equazione valida (per valida intendo che non deve essere <a href="./../../a/af/afbe.html">né impossibile né indeterminata</a>).</p><p>Se noi sottraiamo termine a termine un&#39;equazione dall&#39;altra otteniamo un&#39;equazione di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>primo\xA0grado</mtext></mrow><annotation encoding="application/x-tex">\\text{primo grado}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">primo\xA0grado</span></span></span></span></span> che possiamo sostituire nel sistema ad una qualunque delle due equazioni di partenza e quindi il nostro sistema è diventato di <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>secondo\xA0grado</mtext></mrow><annotation encoding="application/x-tex">\\text{secondo grado}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">secondo\xA0grado</span></span></span></span></span>.</p><blockquote><p>Viene però</p></blockquote>`,7)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};